import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;

import javax.tools.Diagnostic;
import javax.tools.DiagnosticCollector;
import javax.tools.JavaCompiler;
import javax.tools.JavaFileObject;
import javax.tools.StandardJavaFileManager;
import javax.tools.ToolProvider;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * Minimal offline shim for maven-compiler-plugin. Compiles all .java files
 * under the injected source roots with the in-JDK compiler, always with
 * -parameters. Annotation processors on the classpath (e.g. Lombok) run
 * by default.
 */
public class CompilerShimMojo extends AbstractMojo {

    private List<?> compileSourceRoots;
    private File outputDirectory;
    private List<?> classpathElements;
    private String release;
    private String source;
    private String target;
    private String encoding;

    @Override
    public void execute() throws MojoExecutionException {
        if (compileSourceRoots == null || compileSourceRoots.isEmpty()) {
            getLog().info("No sources to compile.");
            return;
        }
        List<File> javaFiles = new ArrayList<>();
        for (Object root : compileSourceRoots) {
            if (root == null) {
                continue;
            }
            File dir = new File(root.toString());
            if (!dir.isDirectory()) {
                continue;
            }
            try (var stream = Files.walk(dir.toPath())) {
                for (Path path : stream.filter(Files::isRegularFile)
                        .filter(p -> p.toString().endsWith(".java")).sorted().toList()) {
                    javaFiles.add(path.toFile());
                }
            } catch (IOException e) {
                throw new MojoExecutionException("Failed to scan sources in " + dir, e);
            }
        }
        if (javaFiles.isEmpty()) {
            getLog().info("No sources to compile.");
            return;
        }
        if (outputDirectory == null) {
            throw new MojoExecutionException("outputDirectory not set");
        }
        outputDirectory.mkdirs();

        List<String> options = new ArrayList<>();
        options.add("-d");
        options.add(outputDirectory.getAbsolutePath());
        if (classpathElements != null && !classpathElements.isEmpty()) {
            StringBuilder cp = new StringBuilder();
            for (Object element : classpathElements) {
                if (element == null) {
                    continue;
                }
                if (cp.length() > 0) {
                    cp.append(File.pathSeparatorChar);
                }
                cp.append(element);
            }
            options.add("-classpath");
            options.add(cp.toString());
        }
        if (release != null && !release.isBlank()) {
            options.add("--release");
            options.add(release.trim());
        } else {
            if (source != null && !source.isBlank()) {
                options.add("-source");
                options.add(source.trim());
            }
            if (target != null && !target.isBlank()) {
                options.add("-target");
                options.add(target.trim());
            }
        }
        options.add("-encoding");
        options.add(encoding == null || encoding.isBlank() ? "UTF-8" : encoding.trim());
        options.add("-parameters");

        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        if (compiler == null) {
            throw new MojoExecutionException("No system Java compiler available (JDK required)");
        }
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        try (StandardJavaFileManager fileManager =
                     compiler.getStandardFileManager(diagnostics, null, null)) {
            Iterable<? extends JavaFileObject> units =
                    fileManager.getJavaFileObjectsFromFiles(javaFiles);
            getLog().info("Compiling " + javaFiles.size() + " source files to " + outputDirectory);
            Boolean ok = compiler.getTask(null, fileManager, diagnostics, options, null, units).call();
            for (Diagnostic<? extends JavaFileObject> d : diagnostics.getDiagnostics()) {
                String msg = d.getKind() + ": " + d.getSource() + ":" + d.getLineNumber()
                        + " " + d.getMessage(null);
                if (d.getKind() == Diagnostic.Kind.ERROR) {
                    getLog().error(msg);
                } else {
                    getLog().warn(msg);
                }
            }
            if (!Boolean.TRUE.equals(ok)) {
                throw new MojoExecutionException("Compilation failed; see diagnostics above.");
            }
        } catch (IOException e) {
            throw new MojoExecutionException("Compilation I/O failure", e);
        }
    }
}
"
}

